<script lang="ts">import {onMount} from 'svelte'; import {createApiClient} from '$lib/api/client'; type E={id:number;command:string;status:string;executed_at:string;error?:string}; let entries=$state<E[]>([]); let error=$state(''); onMount(async()=>{try{entries=(await createApiClient().get<{entries:E[]}>('/api/v1/admin/audit')).entries;}catch(e){error=e instanceof Error?e.message:'Could not load audit log';}});</script>
<svelte:head><title>Audit log | Betrayal Admin</title></svelte:head><main class="min-h-screen bg-slate-950 p-6 text-slate-100"><div class="mx-auto max-w-6xl"><h1 class="text-3xl font-semibold">Audit log</h1>{#if error}<p role="alert" class="mt-6 text-red-300">{error}</p>{:else}<div class="mt-8 space-y-3">{#each entries as e (e.id)}<article class="border border-slate-700 p-4"><div class="flex justify-between"><strong>{e.command}</strong><span>{e.status}</span></div><p class="text-sm text-slate-400">{e.executed_at}</p>{#if e.error}<p class="text-red-300">{e.error}</p>{/if}</article>{/each}</div>{/if}</div></main>
